PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS sources (id TEXT PRIMARY KEY, title TEXT NOT NULL, kind TEXT NOT NULL, url TEXT, sha256 TEXT NOT NULL, char_count INTEGER NOT NULL, segment_count INTEGER NOT NULL, processed_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS segments (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), ordinal INTEGER NOT NULL, start_offset INTEGER NOT NULL, end_offset INTEGER NOT NULL, text_key TEXT NOT NULL, result_json TEXT, status TEXT NOT NULL DEFAULT 'queued', UNIQUE(source_id, ordinal));
CREATE TABLE IF NOT EXISTS worlds (id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), revision INTEGER NOT NULL, lock_version INTEGER NOT NULL DEFAULT 1, document_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS elements (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), kind TEXT NOT NULL, source_name TEXT NOT NULL, revision INTEGER NOT NULL, document_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS elements_world ON elements(world_id);
CREATE TABLE IF NOT EXISTS terms (element_id TEXT NOT NULL REFERENCES elements(id), locale TEXT NOT NULL, source_revision INTEGER NOT NULL, name TEXT NOT NULL, definition TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY(element_id,locale));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, world_id TEXT REFERENCES worlds(id), kind TEXT NOT NULL, status TEXT NOT NULL, stage TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, total INTEGER NOT NULL, payload_json TEXT NOT NULL, error TEXT, lease_until TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS jobs_world ON jobs(world_id,created_at);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, world_id TEXT REFERENCES worlds(id), type TEXT NOT NULL, message TEXT NOT NULL, data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), kind TEXT NOT NULL, revision INTEGER NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), object_key TEXT NOT NULL, content_type TEXT NOT NULL, sha256 TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS releases (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), slug TEXT NOT NULL, revision INTEGER NOT NULL, status TEXT NOT NULL, locales_json TEXT NOT NULL, content_json TEXT NOT NULL, hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS release_active_slug ON releases(slug) WHERE status='active';
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS mutation_guards (id TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), delivered INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_ledger (id TEXT PRIMARY KEY, world_id TEXT REFERENCES worlds(id), job_id TEXT, model TEXT NOT NULL, stage TEXT NOT NULL, status TEXT NOT NULL, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts (bucket TEXT PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operation_keys (key TEXT PRIMARY KEY, body_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL);
